select
id, user_id, resume_id, company_id, jd_job_id, delivery_count, first_delivery_time, latest_delivery_time,
delivery_status, remark, create_time, update_time
from resume_delivery_rel


        and id = #{id}


        and user_id = #{userId}


        and resume_id = #{resumeId}


        and company_id = #{companyId}


        and jd_job_id = #{jdJobId}


        and delivery_count = #{deliveryCount}


        and first_delivery_time = #{firstDeliveryTime}


        and latest_delivery_time = #{latestDeliveryTime}


        and delivery_status = #{deliveryStatus}


        and remark = #{remark}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

